/* Relentless Ram: hostile Juggernauts stay in their run animation and keep
   trying to tackle the marine. Guardian behavior remains diplomatic. */
function zkUpdateRelentlessJuggernaut(game,enemy,delta){
  const data=enemy.userData;
  if(data.guardian)return zkUpdateGuardianJuggernaut(game,enemy,delta);
  zkJuggernautSetRing(enemy,!1);
  data.attackCooldown=Number(data.attackCooldown??0)-delta;
  if(data.juggernautState==="recover"){
    data.stateTimer=Math.min(Number(data.stateTimer??.65),.65)-delta;
    data.hqModel?.update?.(delta,!1,!1);
    if(data.stateTimer<=0)data.juggernautState="pursuit";
    return;
  }
  const desired=game.player.group.position.clone().sub(enemy.position);
  desired.y=0;
  if(desired.lengthSq()<1e-5){
    data.hqModel?.update?.(delta,!1,!1);
    return;
  }
  desired.normalize();
  if(!data.chargeDirection||data.chargeDirection.lengthSq()<1e-5)data.chargeDirection=desired.clone();
  else{
    const steering=Math.min(1,delta*2.15);
    data.chargeDirection.lerp(desired,steering).normalize();
  }
  zkJuggernautTurn(enemy,data.chargeDirection,1.7,delta);
  data.juggernautState="charge";
  const step=6.8*delta;
  const x=Kt.clamp(enemy.position.x+data.chargeDirection.x*step,-82,82);
  const z=Kt.clamp(enemy.position.z+data.chargeDirection.z*step,-82,82);
  data.hqModel?.update?.(delta,!0,!0);
  if(zkJuggernautChargeCollision(game,enemy,x,z)){
    data.stateTimer=Math.min(Number(data.stateTimer??.65),.65);
    return;
  }
  enemy.position.x=x;
  enemy.position.z=z;
  enemy.position.y=game.terrain.heightAt(x,z);
}
const zkRelentlessJuggernautFallback=zR.prototype.updateEnemyUnit;
zR.prototype.updateEnemyUnit=function(enemy,delta){
  if(enemy.userData.enemyType==="juggernaut")return zkUpdateRelentlessJuggernaut(this,enemy,delta);
  return zkRelentlessJuggernautFallback.call(this,enemy,delta);
};

