/* Keep a precise list of the lightweight settlement pieces so an upgraded
   village can replace only its own procedural stand-ins after every GLB is ready. */
const zkTrackedLocalSettlements=PR.prototype.addLocalSettlements;
PR.prototype.addLocalSettlements=function(){
  const childStart=this.group.children.length,territoryStart=this.localTerritories.length;
  const result=zkTrackedLocalSettlements.call(this);
  const added=this.group.children.slice(childStart),centers=this.localTerritories.slice(territoryStart);
  this.localSettlementFallbacks=centers.map(center=>added.filter(object=>Math.hypot(object.position.x-center.x,object.position.z-center.z)<=14.5));
  return result
};

